  // Only update if diagnosis changed
  if (JSON.stringify(diagnosis) !== JSON.stringify(this.currentStallDiagnosis)) {
    this.currentStallDiagnosis = diagnosis;
    this.updateStallWarning(diagnosis);
  }
}

