      </div>
    </div>
  `;

  // Adjust styling based on confidence
  if (diagnosis.confidence === 'low') {
    this.stallWarningPanel.style.background = 'rgba(255, 152, 0, 0.95)'; // Orange for low confidence
  } else if (diagnosis.confidence === 'high') {
